def translate(language: str, key: str, **kwargs: object) -> str:
    """Übersetzt `key` in die gegebene Sprache; unbekannte Schlüssel liefern den Schlüssel selbst zurück.

    Args:
        language: Zielsprache (``"de"``/``"en"``); alles andere fällt auf Deutsch zurück.
        key: Stabiler Übersetzungsschlüssel aus ``STRINGS``.
        **kwargs: Optionale Platzhalterwerte für ``str.format`` (z. B. Pfade, Zahlen).

    Returns:
        Übersetzter (und ggf. formatierter) Text. Bei unbekanntem Schlüssel wird
        der Schlüssel selbst zurückgegeben, damit ein fehlender Eintrag sichtbar
        auffällt statt eine Ausnahme auszulösen.
    """
    entry = STRINGS.get(key)
    if entry is None:
        return key
    lang = language if language in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE
    text = entry.get(lang, entry.get(DEFAULT_LANGUAGE, key))
    if kwargs:
        try:
            return text.format(**kwargs)
        except (KeyError, IndexError, ValueError):
            return text
    return text
